18	// 端云接口地址配置 —— 所有后端 URL 集中在这里，修改时只改本文件即可。
19	// 支持 da3 / vggt-omega 两套后端，UI 上可切换。
20	//
21	// da3 后端:generate 和 guide 分别在不同 host。
22	//   generate → intelligence-hiaicloud.hwcloudtest.cn
23	//   guide    → xsjcamera.rnd.huawei.com
24	//
25	// vggt-omega 后端:统一走 175.155.64.171:61660。
26	
27	export type BackendType = 'da3' | 'vggt-omega';
28	
29	interface GenerateEndpoint {
30	  host: string;       // generate 服务的完整 host (含 scheme)
31	  endpoint: string;   // generate 接口路径
32	  taskBase: string;   // task 轮询路径前缀
33	}
34	
35	interface GuideEndpoint {
36	  host: string;       // guide 服务的完整 host (含 scheme)
37	  inferPath: string;  // infer 接口路径
38	  taskPath: string;   // task 轮询路径
39	}
40	
41	interface BackendProfile {
42	  name: string;             // UI 显示名
43	  generate: GenerateEndpoint;
44	  guide: GuideEndpoint;
45	  // WebSocket 连续引导（替代 HTTP getGuide 的两段式 infer → poll）
46	  wsUrl: string;
47	  wsGuideFrameIntervalMs: number;  // 抽帧间隔 ms
48	  wsGuideMaxFrames: number;        // 最大帧数（超时停止）
49	  pollIntervalMs: number;
50	  pollMaxSeconds: number;
51	  connectTimeoutMs: number;
52	  readTimeoutMs: number;
53	  // Debug: 跳过摄像头抽帧,直接发 rawfile 固定图到云侧
54	  debugUseFixedImage: boolean;
55	  debugFixedImageName: string;
56	}
57	
58	// ── da3 后端 ────────────────────────────────────────────────────────
59	//   generate host = intelligence-hiaicloud.hwcloudtest.cn
60	//   guide host    = xsjcamera.rnd.huawei.com
61	const da3Profile: BackendProfile = {
62	  name: 'Da3',
63	  generate: {
64	    host: 'https://intelligence-hiaicloud.hwcloudtest.cn',
65	    endpoint: '/camera-agent-api/api/generate',
66	    taskBase: '/camera-agent-api/api/task/',
67	  },
68	  guide: {
69	    host: 'https://xsjcamera.rnd.huawei.com',
70	    inferPath: '/mrightserver/uat/camera_agent_guide/infer',
71	    taskPath: '/mrightserver/uat/camera_agent_guide/task',
72	  },
73	  wsUrl: 'wss://xsjcamera.rnd.huawei.com/ws/infer',
74	  wsGuideFrameIntervalMs: 500,
75	  wsGuideMaxFrames: 240,
76	  pollIntervalMs: 1000,
77	  pollMaxSeconds: 120,
78	  connectTimeoutMs: 30000,
79	  readTimeoutMs: 60000,
80	  debugUseFixedImage: false,
81	  debugFixedImageName: 'f001.jpeg',
82	};
83	
84	// ── vggt-omega 后端 ─────────────────────────────────────────────────
85	//   统一 host = http://175.155.64.171:61660
86	//   API 路径待确认,目前用 /vggt_ 前缀占位。
87	const vggtOmegaProfile: BackendProfile = {
88	  name: 'VGGT-Ω',
89	  generate: {
90	    host: 'http://175.155.64.171:61660',
91	    endpoint: '/camera-agent-api/api/generate',
92	    taskBase: '/camera-agent-api/api/task/',
93	  },
94	  guide: {
95	    host: 'http://175.155.64.171:61660',
96	    inferPath: '/mrightserver/uat/camera_agent_guide/infer',
97	    taskPath: '/mrightserver/uat/camera_agent_guide/task',
98	  },
99	  wsUrl: 'ws://175.155.64.171:61660/ws/infer',
100	  wsGuideFrameIntervalMs: 500,
101	  wsGuideMaxFrames: 240,
102	  pollIntervalMs: 1000,
103	  pollMaxSeconds: 120,
104	  connectTimeoutMs: 30000,
105	  readTimeoutMs: 60000,
106	  debugUseFixedImage: false,
107	  debugFixedImageName: 'f001.jpeg',
108	};
109	
110	// ── 注册表 ──────────────────────────────────────────────────────────
111	const PROFILES: Record<BackendType, BackendProfile> = {
112	  'da3': da3Profile,
113	  'vggt-omega': vggtOmegaProfile,
114	};
115	
116	// ── 全局当前后端(默认 da3，UI 可切换，持久化到 preferences) ─────────
117	const PREFS_NAME = 'cloud_config';
118	const PREF_KEY_BACKEND = 'backend_type';
119	const VALID_BACKENDS: BackendType[] = ['da3', 'vggt-omega'];
120	
121	let _currentBackend: BackendType = 'da3';
122	let _prefsReady: boolean = false;
123	
124	// 应用启动时调一次，从磁盘恢复上次选择。如果从未存过则保持默认 'da3'。
125	export async function initBackendType(context: Context): Promise<void> {
126	  try {
127	    const prefs = await dataPreferences.getPreferences(context, PREFS_NAME);
128	    const saved = await prefs.get(PREF_KEY_BACKEND, 'da3');
129	    if (typeof saved === 'string' && VALID_BACKENDS.includes(saved as BackendType)) {
130	      _currentBackend = saved as BackendType;
131	    }
132	    _prefsReady = true;
133	  } catch (e) {
134	    // 馯次安装 / preferences 损坏 → 保持默认
135	    _prefsReady = true;
136	  }
137	}
138	
139	export function getBackendType(): BackendType {
140	  return _currentBackend;
141	}
142	
143	export function setBackendType(t: BackendType, context?: Context): void {
144	  _currentBackend = t;
145	  // 异步写盘，不阻塞 UI
146	  if (context !== undefined && _prefsReady) {
147	    dataPreferences.getPreferences(context, PREFS_NAME).then((prefs) => {
148	      prefs.put(PREF_KEY_BACKEND, t);
149	      prefs.flush();
150	    }).catch(() => {});
151	  }
152	}
153	
154	export function getCloudConfig(): BackendProfile {
155	  return PROFILES[_currentBackend];
156	}
157	
158	export function getBackendLabel(t: BackendType): string {
159	  return PROFILES[t].name;
160	}
161	
162	export function allBackendTypes(): BackendType[] {
163	  return ['da3', 'vggt-omega'];
164	}
