642	  const out: GuideData = {
643	    x:     parseSignedField(raw.x,     ['左'],     ['右']),
644	    y:     parseSignedField(raw.y,     ['下'],     ['上']),
645	    z:     parseSignedField(raw.z,     ['后'],     ['前']),
646	    yaw:   parseSignedField(raw.yaw,   ['左转'],   ['右转']),
647	    // 实测翻转:server "俯拍 N°" → +N,"仰拍 N°" → -N。applyGuide 的 `-Number(g.pitch)` 把它
648	    // 翻成 placeRingAt 期望的最终符号 → mTargetPitch 视觉/对齐方向正确。
649	    pitch: parseSignedField(raw.pitch, ['仰拍'],   ['俯拍']),
650	    roll:  parseSignedField(raw.roll,  ['左倾'],   ['右倾']),
651	    zoom:  parseZoom(raw.zoom)
652	  };
