693	  const url: string = cfgGuideTaskUrl();
694	  while (nowMs() - start < maxMs) {
695	    const parts: MultipartPart[] = [{ name: 'taskid', text: taskid }];
696	    const resp: HttpResult | null = await postMultipart(url, parts);
697	    if (resp === null) {
698	      await sleepMs(cfgPollMs());
699	      continue;
700	    }

513	  // to the existing placeRingAt + applyZoom paths. Designed to be the SINGLE entry the da3
