124	// 应用启动时调一次，从磁盘恢复上次选择。如果从未存过则保持默认 'da3'。
125	export async function initBackendType(context: Context): Promise<void> {
126	  try {
127	    const prefs = await dataPreferences.getPreferences(context, PREFS_NAME);
128	    const saved = await prefs.get(PREF_KEY_BACKEND, 'da3');
129	    if (typeof saved === 'string' && VALID_BACKENDS.includes(saved as BackendType)) {
130	      _currentBackend = saved as BackendType;
131	    }
132	    _prefsReady = true;
133	  } catch (e) {
134	    // 馯次安装 / preferences 损坏 → 保持默认
135	    _prefsReady = true;
136	  }
137	}
138	
139	export function getBackendType(): BackendType {
140	  return _currentBackend;
141	}
142	
143	export function setBackendType(t: BackendType, context?: Context): void {
144	  _currentBackend = t;
145	  // 异步写盘，不阻塞 UI
146	  if (context !== undefined && _prefsReady) {
147	    dataPreferences.getPreferences(context, PREFS_NAME).then((prefs) => {
148	      prefs.put(PREF_KEY_BACKEND, t);
149	      prefs.flush();
150	    }).catch(() => {});
151	  }
152	}
153	
154	export function getCloudConfig(): BackendProfile {
155	  return PROFILES[_currentBackend];
156	}
157	
158	export function getBackendLabel(t: BackendType): string {
159	  return PROFILES[t].name;
160	}
161	
162	export function allBackendTypes(): BackendType[] {
163	  return ['da3', 'vggt-omega'];
164	}
