690	async function pollGuideTask(taskid: string): Promise<GuideData | null> {
691	  const start: number = nowMs();
692	  const maxMs: number = cfgPollMaxS() * 1000;
693	  const url: string = cfgGuideTaskUrl();
694	  while (nowMs() - start < maxMs) {
695	    const parts: MultipartPart[] = [{ name: 'taskid', text: taskid }];
696	    const resp: HttpResult | null = await postMultipart(url, parts);
697	    if (resp === null) {
698	      await sleepMs(cfgPollMs());
699	      continue;
700	    }

513	  // to the existing placeRingAt + applyZoom paths. Designed to be the SINGLE entry the da3
514	  // pose-calc backend (or any other producer) calls: reset prior ring state → place → open AI
515	  // panel, plus a zoom write at the end.
516	  private applyGuide(g: GuideData): void {
517	    let x: number = Number(g.x);
518	    let y: number = Number(g.y);
519	    let z: number = Number(g.z);
520	    let yaw: number = Number(g.yaw);
521	    // 实测:da3"俯拍"经 parse 为正,但 placeRingAt 渲染时正 pitch = 仰(L177 pitchMat 约定),
522	    // 直接透传方向反。取负让 "俯拍 N°" 真正朝下倾。camPitch 补偿在 native 端保留。
523	    let pitch: number = -Number(g.pitch);
524	    let roll: number = Number(g.roll);
525	    let zoom: number = Number(g.zoom);
526	    if (Number.isNaN(x) || Number.isNaN(y) || Number.isNaN(z) ||
527	        Number.isNaN(yaw) || Number.isNaN(pitch) || Number.isNaN(roll)) {
528	      Logger.warn(`[applyGuide] NaN in pose fields, skip: x=${g.x} y=${g.y} z=${g.z} yaw=${g.yaw} pitch=${g.pitch} roll=${g.roll}`);
529	      return;
530	    }
531	    // 清场景(含 native 锚点 detach+release)+ 流程状态。da3 会话/参考图不动 —— applyGuide
532	    // 是同一会话内的 step2,sessionTaskId 和 targetJpeg 后续可能还要用。
533	    this.resetSceneOnly();
534	    // === 符号约定(扶正图标定铁证,横竖屏一致)===
535	    //   da3 输出 = 从当前 B 走到目标 A 的位移向量,用户视角(相机本地):
536	    //     x:+ =用户右  y:+ =用户上(垂直 delta)  z:+ =用户前
537	    //     yaw:+ =右转  pitch:+ =俯  roll:+ =左滚
538	    //   placeRingAt 同语义:x/y/z=用户右/上/前(米),yaw=+右转,pitch=+仰(L177 约定)。
539	    //   ∴ x/y/z/yaw/roll 直传;pitch 反向(da3+俯 vs placeRingAt+仰)→ 取负。
540	    //   roll:native 会丢弃(用 camRoll 自动 snap 横竖),传啥都无效。
541	    //   横竖屏统一:captureJpeg 按 ori 旋转扶正后送 da3,标定工具同套旋转
542	    //   (10 步 × 3 朝向标定主导轴+符号完全一致),故此处不做 orientation 分支。
543	    let id: number = arEngineDemo.placeRingAt(this.idStr, x, y, z, yaw, pitch, roll);
544	    Logger.info(`[applyGuide] placeRingAt(x=${x} y=${y} z=${z} yaw=${yaw} pitch=${pitch} roll=${roll}) -> ${id}, zoom=${zoom}`);
545	    if (id < 0) {
546	      this.toast('请稳住手机等待跟踪稳定');
547	      return;
548	    }
549	    this.ringPlaced = true;
550	    // 注意:不调 enterAiModeAndOpenCard()。applyGuide 是 step2(点参考图)的产物,onTargetTap
551	    // 已主动收起卡片栏让出取景空间;此处再展开会和功能②冲突。panelExpanded(AI 模式)在
552	    // onBeaconTap 时已设好,这里无需重设。卡片保持 onTargetTap 收起的状态,用户点 chevron 可
553	    // 手动展开看参考图。
554	    // 相机焦距暂不自动调整(da3 zoom 先不生效)。ZoomBar / 捏合手动变焦不受影响。
555	    // if (!Number.isNaN(zoom) && zoom > 0) {
556	    //   this.applyZoom(Math.min(5.0, Math.max(1.0, zoom)));
557	    // }

