656	function pickGuideString(out: Record<string, ESObject> | null): GuideData | null {
657	  if (out === null) {
658	    return null;
659	  }
660	  // Server may put guide_string directly, or wrap in {output:{guide_string:{...}}}, or output[0].
661	  let gs: ESObject = out['guide_string'];
662	  if (gs === undefined) {
663	    const inner: Record<string, ESObject> | null = pickObject(out, 'data');
664	    if (inner !== null) {
665	      gs = inner['guide_string'];
666	    }
667	  }
668	  if (gs === undefined || gs === null || typeof gs !== 'object') {
669	    return null;
670	  }
671	  const g: Record<string, ESObject> = gs as Record<string, ESObject>;
672	  const fields: string[] = ['x', 'y', 'z', 'pitch', 'yaw', 'roll', 'zoom'];
673	  const vals: Record<string, string> = {};
674	  for (const k of fields) {
675	    const v: ESObject = g[k];
676	    if (v === undefined || v === null) {
677	      Logger.error(`${TAG} guide_string missing field=${k}`);
678	      return null;
679	    }
680	    vals[k] = String(v);
681	  }
682	  const result: GuideData = {
683	    x: vals['x'], y: vals['y'], z: vals['z'],
684	    pitch: vals['pitch'], yaw: vals['yaw'], roll: vals['roll'],
685	    zoom: vals['zoom']
686	  };
687	  return result;
688	}
