887	
888	    // 注册回调：状态 / pose / 关闭 / 目标图
889	    let imageReceived: boolean = false;
890	    let poseReceived: boolean = false;
891	    let captureInProgress: boolean = false;  // 防重入：一次只允许一个 captureJpeg 在跑
892	
893	    client.setCallbacks(
894	      // onStatus — 等服务端就绪后开始抽帧
895	      (status: string) => {
896	        Logger.info(`ARDA3-WS loop: status=${status}`);
897	        if (status === 'ready') {
898	          frameTimer = setInterval(async (): Promise<void> => {
899	            if (stopped || !this.guideLoopRunning) {
900	              clearInterval(frameTimer);
901	              cleanup();
902	              return;
903	            }
904	            // 已对齐 → 立即停止抽帧

905	            if (this.isLocked) {
906	              Logger.info(`ARDA3-WS loop: LOCKED detected, stopping`);
907	              this.toast('对齐成功!');
908	              cleanup();
909	              return;
910	            }
911	            // 上一帧还在抽 → 跳过本次，等下一拍
912	            if (captureInProgress) {
913	              return;
914	            }
915	
916	            this.guideLoopFrameCount++;
917	            if (this.guideLoopFrameCount > maxFrames) {
918	              Logger.info(`ARDA3-WS loop: max frames ${maxFrames} reached`);
919	              this.toast('机位引导超时，请重试');
920	              cleanup();
921	              return;
922	            }
923	
924	            captureInProgress = true;
925	            let current: ArrayBuffer | null = null;
926	            if (useDebugImage) {
927	              current = await this.loadDebugImage();
928	            } else {
929	              current = await this.captureJpeg();
930	            }
931	            captureInProgress = false;
932	            if (current === null) {
933	              Logger.warn(`ARDA3-WS loop frame ${this.guideLoopFrameCount}: capture failed`);
934	              return;
935	            }
936	
937	            Logger.info(`ARDA3-WS loop frame ${this.guideLoopFrameCount}/${maxFrames}: sending (${current.byteLength}B)`);
938	            client.sendFrame(current);
939	          }, intervalMs);
940	        }
941	      },
942	      // onPose — 云侧推理完成，带回 guide_string
943	      (pose: WsPoseResult): void => {
944	        if (stopped) {
945	          return;
946	        }
947	        // 首帧推理完成 → 云侧已就绪，关掉 spinner
948	        if (!poseReceived) {
949	          poseReceived = true;
950	          this.refLoading = false;
951	          Logger.info('ARDA3-WS loop: first pose received, server ready');
952	        }
953	        const gs: Record<string, ESObject> | undefined = pose.guide_string;
954	        if (gs === undefined) {
955	          Logger.warn('ARDA3-WS loop: pose without guide_string');
956	          return;
957	        }
958	        // 从 WS 提取原始 guide_string（中文方向词），解析为裸数字再喂 applyGuide
959	        const rawGs: Da3GuideData = {
960	          x:     extractGuideField(gs, 'x', '0'),
961	          y:     extractGuideField(gs, 'y', '0'),
962	          z:     extractGuideField(gs, 'z', '0'),
963	          pitch: extractGuideField(gs, 'pitch', '0'),
964	          yaw:   extractGuideField(gs, 'yaw', '0'),
965	          roll:  extractGuideField(gs, 'roll', '0'),
966	          zoom:  extractGuideField(gs, 'zoom', '1'),
967	        };
968	        // parseGuideString 把 "右 0.15 米" 转为 "0.15"，applyGuide 才能 Number() 成功
969	        const parsed: Da3GuideData = parseGuideString(rawGs);
970	        Logger.info(`ARDA3-WS loop frame ${this.guideLoopFrameCount}: raw=${JSON.stringify(rawGs)} parsed=${JSON.stringify(parsed)}`);
971	        this.applyGuide(parsed as GuideData);
972	
973	        setTimeout((): void => {
974	          if (this.isLocked) {
975	            Logger.info(`ARDA3-WS loop: LOCKED at frame ${this.guideLoopFrameCount}`);
976	            this.toast('对齐成功!');
977	            cleanup();
978	          }
979	        }, 150);
980	      },
981	      // onClosed — 连接断开时收尾
982	      (): void => {
983	        Logger.info('ARDA3-WS loop: connection closed');
984	        cleanup();

641	export function parseGuideString(raw: GuideData): GuideData {
642	  const out: GuideData = {
643	    x:     parseSignedField(raw.x,     ['左'],     ['右']),
644	    y:     parseSignedField(raw.y,     ['下'],     ['上']),
645	    z:     parseSignedField(raw.z,     ['后'],     ['前']),
646	    yaw:   parseSignedField(raw.yaw,   ['左转'],   ['右转']),
647	    // 实测翻转:server "俯拍 N°" → +N,"仰拍 N°" → -N。applyGuide 的 `-Number(g.pitch)` 把它
648	    // 翻成 placeRingAt 期望的最终符号 → mTargetPitch 视觉/对齐方向正确。
649	    pitch: parseSignedField(raw.pitch, ['仰拍'],   ['俯拍']),
650	    roll:  parseSignedField(raw.roll,  ['左倾'],   ['右倾']),
651	    zoom:  parseZoom(raw.zoom)
652	  };
653	  return out;
654	}
655	
656	function pickGuideString(out: Record<string, ESObject> | null): GuideData | null {
657	  if (out === null) {
658	    return null;
659	  }
660	  // Server may put guide_string directly, or wrap in {output:{guide_string:{...}}}, or output[0].
661	  let gs: ESObject = out['guide_string'];
662	  if (gs === undefined) {
663	    const inner: Record<string, ESObject> | null = pickObject(out, 'data');
664	    if (inner !== null) {
665	      gs = inner['guide_string'];
666	    }
667	  }
668	  if (gs === undefined || gs === null || typeof gs !== 'object') {
669	    return null;
670	  }
671	  const g: Record<string, ESObject> = gs as Record<string, ESObject>;
672	  const fields: string[] = ['x', 'y', 'z', 'pitch', 'yaw', 'roll', 'zoom'];
673	  const vals: Record<string, string> = {};
674	  for (const k of fields) {
675	    const v: ESObject = g[k];
676	    if (v === undefined || v === null) {
677	      Logger.error(`${TAG} guide_string missing field=${k}`);
678	      return null;
679	    }
680	    vals[k] = String(v);
681	  }
682	  const result: GuideData = {
683	    x: vals['x'], y: vals['y'], z: vals['z'],
684	    pitch: vals['pitch'], yaw: vals['yaw'], roll: vals['roll'],
685	    zoom: vals['zoom']
686	  };
687	  return result;
688	}
689	
690	async function pollGuideTask(taskid: string): Promise<GuideData | null> {
691	  const start: number = nowMs();
692	  const maxMs: number = cfgPollMaxS() * 1000;
693	  const url: string = cfgGuideTaskUrl();
694	  while (nowMs() - start < maxMs) {
695	    const parts: MultipartPart[] = [{ name: 'taskid', text: taskid }];
696	    const resp: HttpResult | null = await postMultipart(url, parts);
697	    if (resp === null) {
698	      await sleepMs(cfgPollMs());
699	      continue;
700	    }

513	  // to the existing placeRingAt + applyZoom paths. Designed to be the SINGLE entry the da3
514	  // pose-calc backend (or any other producer) calls: reset prior ring state → place → open AI
515	  // panel, plus a zoom write at the end.
516	  private applyGuide(g: GuideData): void {
517	    let x: number = Number(g.x);
518	    let y: number = Number(g.y);
519	    let z: number = Number(g.z);
520	    let yaw: number = Number(g.yaw);
521	    // 实测:da3"俯拍"经 parse 为正,但 placeRingAt 渲染时正 pitch = 仰(L177 pitchMat 约定),
522	    // 直接透传方向反。取负让 "俯拍 N°" 真正朝下倾。camPitch 补偿在 native 端保留。
523	    let pitch: number = -Number(g.pitch);
524	    let roll: number = Number(g.roll);
525	    let zoom: number = Number(g.zoom);
526	    if (Number.isNaN(x) || Number.isNaN(y) || Number.isNaN(z) ||
527	        Number.isNaN(yaw) || Number.isNaN(pitch) || Number.isNaN(roll)) {
528	      Logger.warn(`[applyGuide] NaN in pose fields, skip: x=${g.x} y=${g.y} z=${g.z} yaw=${g.yaw} pitch=${g.pitch} roll=${g.roll}`);
529	      return;
530	    }
531	    // 清场景(含 native 锚点 detach+release)+ 流程状态。da3 会话/参考图不动 —— applyGuide
532	    // 是同一会话内的 step2,sessionTaskId 和 targetJpeg 后续可能还要用。
533	    this.resetSceneOnly();
534	    // === 符号约定(扶正图标定铁证,横竖屏一致)===
535	    //   da3 输出 = 从当前 B 走到目标 A 的位移向量,用户视角(相机本地):
536	    //     x:+ =用户右  y:+ =用户上(垂直 delta)  z:+ =用户前
537	    //     yaw:+ =右转  pitch:+ =俯  roll:+ =左滚
538	    //   placeRingAt 同语义:x/y/z=用户右/上/前(米),yaw=+右转,pitch=+仰(L177 约定)。
539	    //   ∴ x/y/z/yaw/roll 直传;pitch 反向(da3+俯 vs placeRingAt+仰)→ 取负。
540	    //   roll:native 会丢弃(用 camRoll 自动 snap 横竖),传啥都无效。
541	    //   横竖屏统一:captureJpeg 按 ori 旋转扶正后送 da3,标定工具同套旋转
542	    //   (10 步 × 3 朝向标定主导轴+符号完全一致),故此处不做 orientation 分支。
543	    let id: number = arEngineDemo.placeRingAt(this.idStr, x, y, z, yaw, pitch, roll);
544	    Logger.info(`[applyGuide] placeRingAt(x=${x} y=${y} z=${z} yaw=${yaw} pitch=${pitch} roll=${roll}) -> ${id}, zoom=${zoom}`);
545	    if (id < 0) {
546	      this.toast('请稳住手机等待跟踪稳定');
547	      return;
548	    }
549	    this.ringPlaced = true;
550	    // 注意:不调 enterAiModeAndOpenCard()。applyGuide 是 step2(点参考图)的产物,onTargetTap
551	    // 已主动收起卡片栏让出取景空间;此处再展开会和功能②冲突。panelExpanded(AI 模式)在
552	    // onBeaconTap 时已设好,这里无需重设。卡片保持 onTargetTap 收起的状态,用户点 chevron 可
553	    // 手动展开看参考图。
554	    // 相机焦距暂不自动调整(da3 zoom 先不生效)。ZoomBar / 捏合手动变焦不受影响。
555	    // if (!Number.isNaN(zoom) && zoom > 0) {
556	    //   this.applyZoom(Math.min(5.0, Math.max(1.0, zoom)));
557	    // }

