5	
6	// v13 (e) — WebSocket 机位引导客户端。替代 HTTP getGuide 的两段式（infer → poll），
7	// 直连云侧 /ws/infer，利用滑动窗口多帧 batch 推理 + GlobalAligner 全局对齐。
8	//
9	// 二进制帧协议（端 → 云）：
10	//   [1B: type=0x01][4B: seq BE][4B: ts_ms BE][JPEG bytes...]
11	//
12	// 控制消息（端 → 云）：
13	//   [1B: type=0x02][4B: 0][4B: 0][1B: action=0x01=RESET]
14	//
15	// 云 → 端（文本 JSON）：
16	//   {"type":"status","status":"ready"}
17	//   {"type":"pose","frame_seq":N,...,"guide_string":{...}}
18	//   {"type":"error","code":"...","detail":"..."}
19	
20	import webSocket from '@ohos.net.webSocket';
21	import { BusinessError } from '@kit.BasicServicesKit';
22	import { systemDateTime } from '@kit.BasicServicesKit';
23	import { Logger } from '../utils/Logger';
24	import { getCloudConfig } from '../config/CloudConfig';
25	
26	const TAG = 'ARDA3-WS';
27	
28	// ── 常量（协议层） ────────────────────────────────────────────
29	const MSG_FRAME: number = 0x01;
30	const MSG_CONTROL: number = 0x02;
31	const CTRL_RESET: number = 0x01;
32	const HEADER_SIZE: number = 9; // 1 type + 4 seq + 4 timestamp_ms
33	
34	// ── 接收数据类型 ──────────────────────────────────────────────
35	
36	// 云侧 pose 响应（包含 guide_string）
37	export interface WsPoseResult {
38	  frame_seq: number;
39	  timestamp_ms: number;
40	  translation: number[];
41	  quaternion: number[];
42	  current_translation: number[];
43	  current_quaternion: number[];
44	  fov: number[];
45	  guide_string?: Record<string, ESObject>;
46	  guidance?: string;
47	}
48	
49	// guide_string 的实际字段（云侧 JSON 中返回的中文方向串）
50	export interface WsGuideString {
51	  x: string;
52	  y: string;
53	  z: string;
54	  yaw: string;
55	  pitch: string;
56	  roll: string;
57	  zoom: string;
58	}
59	
60	// 从 JSON record 中安全提取一个 string 字段
61	export function extractGuideField(gs: Record<string, ESObject>, key: string, defVal: string): string {
62	  const v: ESObject = gs[key];
63	  if (typeof v === 'string') {
64	    return v as string;
65	  }
66	  return defVal;
67	}
68	
69	// 回调类型
70	export type WsStatusCallback = (status: string) => void;
71	export type WsPoseCallback = (pose: WsPoseResult) => void;
72	export type WsClosedCallback = () => void;
73	export type WsImageCallback = (jpegBytes: ArrayBuffer) => void;
74	
75	// ── WebSocket 引导客户端 ─────────────────────────────────────
76	
77	export class WsGuideClient {
78	  private ws: webSocket.WebSocket | null = null;
79	  private seq: number = 0;
80	  private connected: boolean = false;
81	  private onStatus: WsStatusCallback | null = null;
82	  private onPose: WsPoseCallback | null = null;
83	  private onClosed: WsClosedCallback | null = null;
84	  private onImage: WsImageCallback | null = null;
85	
86	  setCallbacks(onStatus: WsStatusCallback | null, onPose: WsPoseCallback | null,
87	              onClosed: WsClosedCallback | null, onImage: WsImageCallback | null): void {
88	    this.onStatus = onStatus;
89	    this.onPose = onPose;
90	    this.onClosed = onClosed;
91	    this.onImage = onImage;
92	  }
93	
94	  connect(): Promise<boolean> {
95	    return new Promise<boolean>((resolve: (v: boolean) => void) => {
96	      try {
97	        this.ws = webSocket.createWebSocket();
98	        const url: string = getCloudConfig().wsUrl;
99	        Logger.info(`${TAG} connecting to ${url}`);
100	
101	        this.ws.connect(url, (err: BusinessError, value: boolean) => {
102	          if (err) {
103	            Logger.error(`${TAG} connect FAIL: code=${err.code} msg=${err.message}`);
104	            resolve(false);
105	            return;
106	          }
107	          Logger.info(`${TAG} connect OK ready=${value}`);
108	
109	          // 注册事件
110	          this.ws!.on('message', (err: BusinessError, value: string | ArrayBuffer) => {
111	            if (err) {
112	              Logger.error(`${TAG} onMessage error: ${err.message}`);
113	              return;
114	            }
115	            this._handleMessage(value);
116	          });
117	
118	          this.ws!.on('close', (err: BusinessError, value: webSocket.CloseResult) => {
119	            Logger.info(`${TAG} closed code=${value.code} reason=${value.reason}`);
120	            this.connected = false;
121	            if (this.onClosed) {
122	              this.onClosed();
123	            }
124	          });
125	
126	          this.ws!.on('error', (err: BusinessError) => {
127	            Logger.error(`${TAG} error: code=${err.code} msg=${err.message}`);
128	          });
129	
130	          this.connected = true;
131	          resolve(true);
132	        });
133	      } catch (e) {
134	        const exc: BusinessError = e as BusinessError;
135	        Logger.error(`${TAG} connect exception: ${exc.message}`);
136	        resolve(false);
137	      }
138	    });
139	  }
140	
141	  // 发送一帧 JPEG（按协议打包二进制帧头）
142	  sendFrame(jpegBytes: ArrayBuffer): boolean {
143	    if (!this.ws || !this.connected) {
144	      return false;
145	    }
146	
147	    this.seq++;
148	    const ts: number = Math.floor(systemDateTime.getTime(false));
149	    const payloadLen: number = jpegBytes.byteLength;
150	    const totalLen: number = HEADER_SIZE + payloadLen;
151	
152	    // 打包 header + body 到一个 ArrayBuffer
153	    const packet: ArrayBuffer = new ArrayBuffer(totalLen);
154	    const view: DataView = new DataView(packet);
155	    view.setUint8(0, MSG_FRAME);
156	    view.setUint32(1, this.seq, false);   // big-endian
157	    view.setUint32(5, ts, false);
158	
159	    // 拷贝 JPEG 字节
160	    const pkt8: Uint8Array = new Uint8Array(packet);
161	    const jpg8: Uint8Array = new Uint8Array(jpegBytes);
162	    pkt8.set(jpg8, HEADER_SIZE);
163	
164	    this.ws.send(packet, (err: BusinessError) => {
165	      if (err) {
166	        Logger.error(`${TAG} send frame ${this.seq} FAIL: ${err.message}`);
167	      }
168	    });
169	
170	    Logger.info(`${TAG} sent frame seq=${this.seq} ts=${ts} jpeg=${payloadLen}B`);
171	    return true;
172	  }
173	
174	  // 发送 RESET 控制消息
175	  sendReset(): void {
176	    if (!this.ws || !this.connected) {
177	      return;
178	    }
179	    const pkt: ArrayBuffer = new ArrayBuffer(HEADER_SIZE + 1);
180	    const view: DataView = new DataView(pkt);
181	    view.setUint8(0, MSG_CONTROL);
182	    view.setUint32(1, 0, false);
183	    view.setUint32(5, 0, false);
184	    view.setUint8(9, CTRL_RESET);
185	
186	    this.ws.send(pkt, (err: BusinessError) => {
187	      if (err) {
188	        Logger.error(`${TAG} send reset FAIL: ${err.message}`);
189	      }
190	    });
191	    Logger.info(`${TAG} sent reset`);
192	  }
193	
194	  close(): void {
195	    if (this.ws && this.connected) {
196	      this.connected = false;
197	      this.ws.close({ code: 1000, reason: 'client done' }, (err: BusinessError) => {
198	        if (err) {
199	          Logger.warn(`${TAG} close error: ${err.message}`);
200	        }
201	      });
202	    }
203	  }
204	
