98	        const url: string = getCloudConfig().wsUrl;
99	        Logger.info(`${TAG} connecting to ${url}`);
100	
101	        this.ws.connect(url, (err: BusinessError, value: boolean) => {
102	          if (err) {
103	            Logger.error(`${TAG} connect FAIL: code=${err.code} msg=${err.message}`);
104	            resolve(false);
105	            return;
106	          }
107	          Logger.info(`${TAG} connect OK ready=${value}`);
108	
109	          // 注册事件
110	          this.ws!.on('message', (err: BusinessError, value: string | ArrayBuffer) => {
111	            if (err) {
112	              Logger.error(`${TAG} onMessage error: ${err.message}`);
113	              return;
114	            }
115	            this._handleMessage(value);
116	          });
117	
118	          this.ws!.on('close', (err: BusinessError, value: webSocket.CloseResult) => {
119	            Logger.info(`${TAG} closed code=${value.code} reason=${value.reason}`);
120	            this.connected = false;
121	            if (this.onClosed) {
122	              this.onClosed();
123	            }
124	          });
125	
126	          this.ws!.on('error', (err: BusinessError) => {
127	            Logger.error(`${TAG} error: code=${err.code} msg=${err.message}`);
128	          });
129	
130	          this.connected = true;
131	          resolve(true);
132	        });
133	      } catch (e) {
134	        const exc: BusinessError = e as BusinessError;
135	        Logger.error(`${TAG} connect exception: ${exc.message}`);
136	        resolve(false);
137	      }
