177	      return;
178	    }
179	    const pkt: ArrayBuffer = new ArrayBuffer(HEADER_SIZE + 1);
180	    const view: DataView = new DataView(pkt);
181	    view.setUint8(0, MSG_CONTROL);
182	    view.setUint32(1, 0, false);
183	    view.setUint32(5, 0, false);
184	    view.setUint8(9, CTRL_RESET);
185	
186	    this.ws.send(pkt, (err: BusinessError) => {
187	      if (err) {
188	        Logger.error(`${TAG} send reset FAIL: ${err.message}`);
189	      }
190	    });
191	    Logger.info(`${TAG} sent reset`);
192	  }
193	
194	  close(): void {
195	    if (this.ws && this.connected) {
196	      this.connected = false;
197	      this.ws.close({ code: 1000, reason: 'client done' }, (err: BusinessError) => {
198	        if (err) {
