200	        }
201	      });
202	    }
203	  }
204	
205	  // ── 内部方法 ──────────────────────────────────────────────
206	
207	  private _handleMessage(value: string | ArrayBuffer): void {
208	    if (typeof value === 'string') {
209	      this._handleText(value);
210	    } else {
