212	      const buf: ArrayBuffer = value as ArrayBuffer;
213	      if (buf.byteLength > HEADER_SIZE) {
214	        const view: DataView = new DataView(buf);
215	        const msgType: number = view.getUint8(0);
216	        if (msgType === 0x03 && this.onImage) {
217	          const seq: number = view.getUint32(1, false);
218	          const jpegLen: number = buf.byteLength - HEADER_SIZE;
219	          const jpeg: ArrayBuffer = new ArrayBuffer(jpegLen);
220	          const dst: Uint8Array = new Uint8Array(jpeg);
221	          const src: Uint8Array = new Uint8Array(buf, HEADER_SIZE, jpegLen);
222	          dst.set(src);
223	          Logger.info(`${TAG} recv generated image seq=${seq} jpeg=${jpegLen}B`);
224	          this.onImage(jpeg);
225	        } else {
226	          Logger.info(`${TAG} recv binary ${buf.byteLength}B type=0x${msgType.toString(16)} (no handler)`);
227	        }
228	      } else {
229	        Logger.info(`${TAG} recv binary ${buf.byteLength}B (too short)`);
230	      }
231	    }
232	  }
233	
234	  private _handleText(text: string): void {
235	    try {
236	      const msg: Record<string, ESObject> = JSON.parse(text) as Record<string, ESObject>;
237	      const msgType: string = (msg['type'] as string) || '';
238	
239	      if (msgType === 'status') {
240	        const s: string = (msg['status'] as string) || '';
241	        Logger.info(`${TAG} recv status: ${s}`);
242	        if (this.onStatus) {
243	          this.onStatus(s);
244	        }
245	      } else if (msgType === 'pose') {
246	        const guide: Record<string, ESObject> | undefined =
247	          msg['guide_string'] !== undefined ? msg['guide_string'] as Record<string, ESObject> : undefined;
248	        if (guide !== undefined) {
249	          Logger.info(`${TAG} recv pose frame_seq=${msg['frame_seq']} guide=${JSON.stringify(guide)}`);
250	        } else {
251	          Logger.info(`${TAG} recv pose frame_seq=${msg['frame_seq']} (no guide_string)`);
252	        }
253	        if (this.onPose) {
254	          this.onPose(msg as Record<string, ESObject> as WsPoseResult);
255	        }
256	      } else if (msgType === 'vision') {
257	        Logger.info(`${TAG} recv vision: ${text}`);
258	      } else if (msgType === 'error') {
259	        Logger.error(`${TAG} recv error: ${text}`);
260	      } else {
261	        Logger.warn(`${TAG} recv unknown type=${msgType}: ${text}`);
262	      }
263	    } catch (e) {
264	      Logger.warn(`${TAG} JSON parse failed: ${(e as Error).message} raw=${text.substring(0, 200)}`);
265	    }
266	  }
267	}
